<?php

declare(strict_types=1);

namespace Glueful\Tests\Unit\Console\Commands\Database;

use Glueful\Bootstrap\ApplicationContext;
use Glueful\Console\Commands\Database\SeedCommand;
use PHPUnit\Framework\TestCase;
use Psr\Container\ContainerInterface;
use Psr\Container\NotFoundExceptionInterface;
use Symfony\Component\Console\Tester\CommandTester;

/**
 * A seeder generated by scaffold:seeder is a plain app class that no provider registers. db:seed
 * (and Seeder::call()) asked the container for it, which only builds registered services, so
 * every app seeder failed with "Service '…' not found".
 */
final class SeedCommandRunsAppSeedersTest extends TestCase
{
    /** @var list<string> */
    public static array $ran = [];

    public static function setUpBeforeClass(): void
    {
        if (!class_exists('App\\Database\\Seeders\\ProbeRunsChildSeeder', false)) {
            eval(<<<'PHP'
                namespace App\Database\Seeders;
                use Glueful\Tests\Unit\Console\Commands\Database\SeedCommandRunsAppSeedersTest as T;
                class ProbeDependencySeeder extends \Glueful\Database\Seeders\Seeder {
                    public function run(): void { T::$ran[] = 'dependency'; }
                }
                class ProbeChildSeeder extends \Glueful\Database\Seeders\Seeder {
                    public function run(): void { T::$ran[] = 'child'; }
                }
                class ProbeRunsChildSeeder extends \Glueful\Database\Seeders\Seeder {
                    protected array $dependencies = [ProbeDependencySeeder::class];
                    public function run(): void { T::$ran[] = 'parent'; $this->call(ProbeChildSeeder::class); }
                }
                PHP);
        }
    }

    public function testRunsAnUnregisteredAppSeederItsDependenciesAndCalledSeeders(): void
    {
        self::$ran = [];
        $context = new ApplicationContext(sys_get_temp_dir(), 'testing');
        $container = new class ($context) implements ContainerInterface {
            public function __construct(private ApplicationContext $context)
            {
            }

            public function get(string $id): mixed
            {
                if ($id === ApplicationContext::class) {
                    return $this->context;
                }
                throw new class ("Service '{$id}' not found") extends \RuntimeException implements
                    NotFoundExceptionInterface {
                };
            }

            public function has(string $id): bool
            {
                return $id === ApplicationContext::class;
            }
        };

        $tester = new CommandTester(new SeedCommand($container, $context));
        $status = $tester->execute(['class' => 'ProbeRunsChildSeeder', '--force' => true], ['interactive' => false]);

        self::assertSame(0, $status, $tester->getDisplay());
        self::assertSame(['dependency', 'parent', 'child'], self::$ran);
    }
}
